package mx.com.mesaregia.pagos.application.service.impl;
import mx.com.mesaregia.pagos.api.request.CompensacionCreateRequest; import mx.com.mesaregia.pagos.api.response.*; import mx.com.mesaregia.pagos.application.service.MovimientoCuentaService; import mx.com.mesaregia.pagos.exception.*; import mx.com.mesaregia.pagos.repository.*; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.stereotype.Service;
@Service public class MovimientoCuentaServiceImpl implements MovimientoCuentaService {private final MovimientoCuentaRepository movs;private final CompensacionWriteService writer;private final CuentaCobroServiceImpl cuentas;public MovimientoCuentaServiceImpl(MovimientoCuentaRepository m,CompensacionWriteService w,CuentaCobroServiceImpl c){movs=m;writer=w;cuentas=c;}
 @Override public CompensacionResponse compensar(Long idPago,String key,CompensacionCreateRequest r){validar(key);try{var x=writer.compensar(idPago,key,r);return respuesta(x.idMovimiento(),x.idempotente());}catch(DataIntegrityViolationException e){var m=movs.findByClaveOperacion(key).orElseThrow(()->e);return respuesta(m.getId(),true);}}
 private CompensacionResponse respuesta(Long id,boolean idem){var m=movs.findDetailedById(id).orElseThrow(()->new ResourceNotFoundException("Movimiento compensatorio no encontrado"));var p=m.getPago();return new CompensacionResponse(m.getId(),m.getFolio(),idem,p.getId(),p.getFolio(),cuentas.obtenerPorId(m.getCuentaCobro().getId()));}
 private void validar(String k){if(k==null||k.isBlank())throw new BusinessRuleException("Idempotency-Key es obligatorio");if(k.length()>120)throw new BusinessRuleException("Idempotency-Key no puede exceder 120 caracteres");}
}
